A **class** describes a kind of thing: what data it holds (**attributes**) and what it can do (**methods**). An **object** (instance) is one actual thing made from that blueprint.

class Account:
    def __init__(self, owner, balance=0):
        self.owner = owner
        self._balance = balance

    def deposit(self, amount):
        if amount <= 0:
            raise ValueError('Deposit must be positive')
        self._balance += amount

    def withdraw(self, amount):
        if amount > self._balance:
            raise ValueError('Insufficient funds')
        self._balance -= amount

    @property
    def balance(self):
        return self._balance

meena = Account('Meena', 500)
meena.deposit(200)
print(meena.balance)   # 700

class Account {
  #balance = 0;              // truly private field
  constructor(owner, balance = 0) { this.owner = owner; this.#balance = balance; }
  deposit(a) { if (a <= 0) throw new Error('Positive only'); this.#balance += a; }
  get balance() { return this.#balance; }
}
const a = new Account('Meena', 500);
a.deposit(200);
console.log(a.balance); // 700

class Vehicle:
    def __init__(self, reg, max_kg):
        self.reg, self.max_kg = reg, max_kg
    def cost(self, km):
        raise NotImplementedError

class Bike(Vehicle):
    def cost(self, km):
        return 4 * km

class Truck(Vehicle):
    def cost(self, km):
        return 25 * km + 500   # loading fee

A Bike **is a** Vehicle: it inherits __init__ and **overrides** cost(). super().__init__(...) calls the parent's version when you extend it.

class ElectricMotor:
    def cost_per_km(self): return 1.5
class DieselEngine:
    def cost_per_km(self): return 9

class Van:
    def __init__(self, reg, engine):
        self.reg, self.engine = reg, engine
    def cost(self, km):
        return self.engine.cost_per_km() * km

van = Van('KL-07-5', ElectricMotor())

Engines can be swapped without new subclasses. Composition keeps classes small and avoids deep, fragile hierarchies.

