def test_normal():
    assert final_price(1000, 20) == 800
def test_free():
    assert final_price(1000, 100) == 0
def test_invalid():
    with pytest.raises(ValueError):
        final_price(1000, 120)

Run with: pytest. In JavaScript, Jest or Vitest look similar: expect(finalPrice(1000, 20)).toBe(800).

