function applyGate(s, U) {
  const [a, b] = s;
  return [U[0][0] * a + U[0][1] * b, U[1][0] * a + U[1][1] * b];
}
const r = 1 / Math.sqrt(2);
const X = [[0, 1], [1, 0]];
const H = [[r, r], [r, -r]];
let s = [1, 0];
s = applyGate(s, X);
s = applyGate(s, H);
console.log(s.map(v => (Math.round(v * 1e4) / 1e4 + 0).toFixed(4)).join(" "));

import math

def probs(state, n):
    out = []
    for i, a in enumerate(state):
        p = abs(a) ** 2
        if p > 1e-9:
            out.append(format(i, f"0{n}b") + f" {p:.4f}")
    return out

